// A controlled-clock, synthetic kernel scenario, not a user transaction or a
// commercial interest receipt. Amounts are generated by the actual domain
// execution/accrual/repayment functions and persisted atomically with Evidence.
import assert from "node:assert/strict";
import {
  createCreditIntent, createDeterministicCreditDecisionOutcome,
  createCreditOfferAcceptance, createAcceptedOfferObligation, acceptCreditOffer,
  executeSandboxObligation, postSandboxRepayment, createCreditEvent,
  CreditEventType, hashId, SYNTHETIC_FEE_PROFILE
} from "../../../../packages/domain/src/index.js";
import {
  CoreProjectionType, PostgresCoreRepository, PostgresEventRepository,
  createTenantSecurityContext
} from "../../../persistence/src/index.js";
import { AUTHORIZATION_POLICY_VERSION } from "../../../authorization/src/index.js";
import { SignedSandboxRailAdapter } from "../../../sandbox-rail/src/index.js";

export async function persistSyntheticFeeInterestScenario({ pool, tenantId, actorId, subjectId, principalId, consentId, assessmentEnabled = true, feeProfile=SYNTHETIC_FEE_PROFILE, feeInstitutionId }) {
  const start = new Date("2026-09-01T00:00:00Z"), repaidAt = new Date("2026-10-11T00:00:00Z");
  const context = createTenantSecurityContext({ tenantId, actorId, policyVersion: AUTHORIZATION_POLICY_VERSION, source: "local_test" });
  const events = new PostgresEventRepository({ pool, tenantContext: context });
  const core = new PostgresCoreRepository({ pool, eventRepository: events });
  const submitted = createCreditIntent({ subjectId, principalId, authorityType: "consent", authorityRef: consentId,
    assetId: "urn:ipo-one:sandbox-asset:usd-cent", requestedPrincipalMinor: "100000", purposeCode: "working_capital",
    requestedTermDays: assessmentEnabled ? 90 : 89, repaymentFrequency: "end_of_term", installmentCount: 1, now: start });
  const intent = { ...submitted, status: "decided" };
  const { decision, offer } = createDeterministicCreditDecisionOutcome({ intent: submitted, feeProfile, feeInstitutionId, now: start });
  const acceptance = createCreditOfferAcceptance({ intent, decision, offer, authorityType: "consent", authorityRef: consentId,
    acknowledgementHash: hashId("controlled_synthetic_fee_terms", offer.termsHash), acceptedByActorId: actorId, now: start });
  const acceptedOffer=acceptCreditOffer(offer,{expectedOfferHash:offer.creditOfferHash,expectedTermsHash:offer.termsHash,acceptanceId:acceptance.creditOfferAcceptanceId,now:start});
  const obligation = createAcceptedOfferObligation({ intent, decision, offer:acceptedOffer, acceptance, now: start });
  const commit = async (phase, version, when, type, values, payload) => {
    const event = createCreditEvent({ eventType: type, subjectId, obligationId: obligation.obligationId,
      payload: { ...payload, actorId, source: "controlled_clock_synthetic_kernel_fixture", syntheticOnly: true, productionFundsMoved: false }, now: when });
    return core.commitCommand({ aggregateType: "obligation", aggregateId: obligation.obligationId,
      idempotencyKey: `b4-scenario-${obligation.obligationId}-${phase}`,
      commandHash: hashId("synthetic_fee_fixture", { obligationId: obligation.obligationId, phase }),
      events: [{ aggregateType: "obligation", aggregateId: obligation.obligationId, expectedVersion: version, event }],
      writes: values.map(([projection, value]) => ({ type: projection, value, eventId: event.eventId })),
      response: { phase, syntheticOnly: true } });
  };
  await commit("offered",0,start,CreditEventType.CREDIT_OFFER_CREATED,[
    [CoreProjectionType.CREDIT_INTENT,intent],[CoreProjectionType.RISK_DECISION,decision],
    [CoreProjectionType.CREDIT_OFFER,offer]
  ],{offerHash:offer.creditOfferHash,termsHash:offer.termsHash});
  await commit("accepted",1,start,CreditEventType.CREDIT_OFFER_ACCEPTED,[
    [CoreProjectionType.CREDIT_OFFER_ACCEPTANCE,acceptance],[CoreProjectionType.CREDIT_OFFER,acceptedOffer],
    [CoreProjectionType.OBLIGATION,obligation]
  ],{offerHash:offer.creditOfferHash,termsHash:offer.termsHash});
  // The fixture is not a Human authorization proof. Declare its canonical
  // Tenant resource so protected tenant-level operator reads can verify it.
  await events.withTenantWrite(client=>client.query(`INSERT INTO authorization_resources(
    tenant_id,resource_type,resource_id,status,version,created_at,updated_at,schema_version)
    VALUES($1,'obligation',$2,'active',1,$3,$3,'authorization_resource.v1')`,[tenantId,obligation.obligationId,start]));
  const rail=new SignedSandboxRailAdapter();
  const request={obligationId:obligation.obligationId,assetId:obligation.assetId,amountMinor:obligation.originalPrincipalMinor,
    requestId:`request-${obligation.obligationId}`,correlationId:`correlation-${obligation.obligationId}`,issuedAt:start.toISOString()};
  const adapterReceipt=await rail.execute(request);rail.verify(adapterReceipt,request);
  const execution=executeSandboxObligation(obligation,{adapterReceipt,now:start});
  const feeEntry=(result)=>({...result.feeEntry,...(result.feeTransaction?{ledgerTransactionId:result.feeTransaction.ledgerTransactionId}:{})});
  await commit("executed",2,start,CreditEventType.OBLIGATION_SANDBOX_EXECUTED,[
    ...Object.values(execution.accounts).map(a=>[CoreProjectionType.LEDGER_ACCOUNT,a]),
    [CoreProjectionType.LEDGER_TRANSACTION,execution.ledgerTransaction],
    [CoreProjectionType.SANDBOX_EXECUTION_RECEIPT,execution.receipt],
    [CoreProjectionType.LEDGER_TRANSACTION,execution.feeTransaction],
    [CoreProjectionType.SYNTHETIC_FEE_ENTRY,feeEntry(execution)],
    [CoreProjectionType.OBLIGATION,execution.obligation]
  ],{receiptHash:execution.receipt.receiptHash,feeEntry:feeEntry(execution)});
  const repayment=postSandboxRepayment(execution.obligation,{amountMinor:"101086",sourceCode:"synthetic_wallet",actorId,
    syntheticFeeAssessmentEnabled:assessmentEnabled,now:repaidAt});
  assert.equal(repayment.repayment.appliedInterestMinor,"986");
  assert.equal(repayment.obligation.syntheticFees.institutionAssessedMinor,assessmentEnabled?"98":"0");
  await commit("repaid",3,repaidAt,CreditEventType.REPAYMENT_POSTED,[
    [CoreProjectionType.LEDGER_TRANSACTION,repayment.interestTransaction],
    [CoreProjectionType.LEDGER_TRANSACTION,repayment.ledgerTransaction],
    ...(repayment.feeTransaction?[[CoreProjectionType.LEDGER_TRANSACTION,repayment.feeTransaction]]:[]),
    [CoreProjectionType.REPAYMENT,repayment.repayment],
    [CoreProjectionType.SYNTHETIC_FEE_ENTRY,feeEntry(repayment)],
    [CoreProjectionType.OBLIGATION,repayment.obligation]
  ],{repayment:repayment.repayment,feeEntry:feeEntry(repayment)});
  assert.equal((await core.verifyProjection(CoreProjectionType.OBLIGATION,obligation.obligationId)).matches,true);
  return { obligation:repayment.obligation, entry:feeEntry(repayment), core, eventRepository:events };
}
